+// workerReadiness keeps a dead supervised loop from looking healthy merely
+// because its NATS connection remains established. A ShutdownGroup loop
+// failure cancels groupCtx with that failure as its cause; ordinary process
+// cancellation is reported as shutdown rather than as a subsystem fault.
+func workerReadiness(groupCtx context.Context, natsConnected bool) (bool, string) {
+	if groupCtx.Err() != nil {
+		if cause := context.Cause(groupCtx); cause != nil && !errors.Is(cause, context.Canceled) {
+			return false, "worker subsystem failed: " + cause.Error()
+		}
+		return false, "worker shutting down"
+	}
